-- Compact current supplier-state projection for bounded clients.
create or replace function public.get_supplier_current_balances(p_boutique_id text) returns table(supplier_id bigint,balance numeric) language sql stable security definer set search_path='pg_catalog','public','private' as $function$ select s.id,greatest(0::numeric,coalesce((select sum(e.qty*coalesce(e.prix_unit,0)) from public.stock_entries e where e.boutique_id=p_boutique_id and e.supplier_id=s.id and e.qty>0 and e.type in ('achat','ajustement')),0)+coalesce((select sum(c.montant) from public.charges c where c.boutique_id=p_boutique_id and c.supplier_id=s.id and c.source='transfer'),0)-coalesce((select sum(c.montant) from public.charges c where c.boutique_id=p_boutique_id and c.supplier_id=s.id and c.source is distinct from 'transfer' and c.source is distinct from 'supplier_receipt'),0)-coalesce((select sum(c.paid_amount) from public.charges c where c.boutique_id=p_boutique_id and c.supplier_id=s.id and c.source='transfer'),0))::numeric from public.suppliers s where s.boutique_id=p_boutique_id and ((select private.auth_is_super_admin()) or ((select private.auth_is_active_user()) and exists(select 1 from public.boutique_assignments ba where ba.boutique_id=p_boutique_id and ba.user_id=(select auth.uid())))); $function$; revoke all on function public.get_supplier_current_balances(text) from public,anon; grant execute on function public.get_supplier_current_balances(text) to authenticated;
